def load_lm():
    kwargs = {
        "dtype": torch.bfloat16,
        "attn_implementation": mcfg.get("attn_implementation", "sdpa"),
    }
    quantized = bool(mcfg.get("load_in_4bit", False))
    if quantized:  # QLoRA: NF4 base, bf16 compute
        from transformers import BitsAndBytesConfig

        kwargs["quantization_config"] = BitsAndBytesConfig(
            load_in_4bit=True,
            bnb_4bit_quant_type="nf4",
            bnb_4bit_compute_dtype=torch.bfloat16,
            bnb_4bit_use_double_quant=True,
        )
        kwargs["device_map"] = {"": device}
    last_err = None
    for cls in auto_classes:
        try:
            lm = cls.from_pretrained(mcfg["name"], **kwargs)
            return lm if quantized else lm.to(device)
        except ValueError as e:  # config not handled by this auto class
            last_err = e
    raise last_err

model = load_lm()
if mcfg.get("load_in_4bit", False):
    from peft import prepare_model_for_kbit_training

    model = prepare_model_for_kbit_training(
        model,
        use_gradient_checkpointing=mcfg.get("gradient_checkpointing", False),
    )
